/// Priorità del processo dummy
const natl DUMMY_PRIORITY = 0;

// ( ESAME 2024-09-11


/// @brief Tipo di lock posseduto da un processo su un rwlock
enum rw_states { 
	RW_NONE,	///< nessun lock
	RW_WRITER,	///< lock in scrittura
	RW_READER,	///< lock in lettura
	RW_UPGRADED	///< lock in lettura trasfromato in scrittura
