#
# La variabile di ambiente LDFLAGS può essere usata per passare ulteriori argomenti.
NLDFLAGS=			\
        -nostdlib		\
	--no-relax		\
	-z noexecstack		\
	-z norelro		\
	-L$(CE_LIB64)		\
