	@PROJECT_NUMBER=$(CE_ESAME) doxygen
	@sed -i -e 's|\([a-z>")]\)\.\([A-Z<]\)|\1\.<p>\2|g;s|$$\([^$$]*\)\$$|<i>\1</i>|g;s|\\math[a-z]*{\([^}]*\)}|\1|g' doc/html/group__esame.html

