 */
extern "C" void* phys_alloc(size_t size, std::align_val_t align);

/**
 * @brief Dealloca memoria allocata tramite @ref phys_alloc().
 *
 * @param ptr		puntatore alla memoria da liberare
 */
extern "C" void phys_dealloc(void *ptr);
